const crypto = require('crypto');
const item = $input.first().json;
const body = item.body || {};
const signature = (item.headers && item.headers['x-quantive-signature']) || '';
const secret = process.env.WEBHOOK_SECRET || '';
const payload = JSON.stringify(body);
const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex');
let valid = false;
try {
  const a = Buffer.from(signature, 'hex');
  const b = Buffer.from(expected, 'hex');
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) { valid = false; }
if (!valid) {
  try {
    await Postgres.main.query(`INSERT INTO workflows.workflow_errors (workflow_id, workflow_name, execution_id, error_type, message, node_id, node_type, severity, created_at) VALUES ('wf1-sales-crm','WF-1: Sales & CRM',$1,'webhook.auth','Invalid HMAC on /lead-capture','Verify Lead HMAC','webhook','high',CURRENT_TIMESTAMP)`, [$execution.id]);
  } catch (e) {}
  return [];
}
return [item];

