const deal = $input.first().json.body;
if (!deal || !deal.email) throw new Error('Deal missing email');
const postgres = Postgres.main;
const dealResult = await postgres.query(`INSERT INTO deals (lead_email, company, value, stage, closed_at, created_at) VALUES ($1, $2, $3, 'closed_won', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) RETURNING id`, [deal.email, deal.company, deal.value]);
const customerResult = await postgres.query(`INSERT INTO customers (email, name, company, deal_id, plan, status, created_at) VALUES ($1, $2, $3, $4, $5, 'active', CURRENT_TIMESTAMP) RETURNING id`, [deal.email, deal.name, deal.company, dealResult.rows[0].id, deal.plan || 'starter']);
await postgres.query(`UPDATE leads SET status = 'converted', updated_at = CURRENT_TIMESTAMP WHERE email = $1`, [deal.email]);
await postgres.query(`INSERT INTO mrr_events (customer_id, amount, event_type, created_at) VALUES ($1, $2, 'subscription.created', CURRENT_TIMESTAMP)`, [customerResult.rows[0].id, deal.value || 0]);

const isLarge = (deal.value || 0) >= 10000;
return [{ json: { dealId: dealResult.rows[0].id, customerId: customerResult.rows[0].id, email: deal.email, value: deal.value || 0, channel: '#sales-closed', severity: isLarge ? 'high' : 'low', dedupeKey: `deal_${deal.email}_${dealResult.rows[0].id}`, text: isLarge ? `💰 *LARGE DEAL CLOSED!*
*Customer:* ${deal.email}
*Deal ID:* ${dealResult.rows[0].id}
*Value:* $${deal.value}
> 🎉 Congratulations!` : `✅ *Deal Closed*
*Customer:* ${deal.email}
*Deal ID:* ${dealResult.rows[0].id}
*Value:* $${deal.value}` } }];

