return [item];

const update = $input.first().json.body;
if (!update || !update.dealId || !update.stage) throw new Error('Stage payload missing required fields');
const postgres = Postgres.main;
const prev = await postgres.query(`SELECT stage FROM deals WHERE id = $1`, [update.dealId]);
const prevStage = prev.rows[0]?.stage || 'unknown';
await postgres.query(`UPDATE deals SET stage = $1, updated_at = CURRENT_TIMESTAMP WHERE id = $2`, [update.stage, update.dealId]);
const isClosed = ['closed_won', 'closed_lost'].includes(update.stage);
const direction = isClosed ? 'closed' : (['discovery', 'proposal', 'negotiation'].includes(update.stage) ? 'forward' : 'backward');
const severity = isClosed ? 'high' : (direction === 'backward' ? 'medium' : 'low');
const emoji = isClosed ? '🏁' : (direction === 'forward' ? '📈' : '📉');
return [{ json: { dealId: update.dealId, prevStage, newStage: update.stage, channel: '#sales-pipeline', severity, dedupeKey: `stage_${update.dealId}_${update.stage}`, text: `${emoji} *Deal ${isClosed ? update.stage : direction === 'forward' ? 'Moved Forward' : 'Moved Backward'}*
*Deal:* ${update.dealId}
*${prevStage}* → *${update.stage}*`, metadata: { flow: 'deal_stage', dealId: update.dealId, prevStage, newStage: update.stage } } }];

const postgres = Postgres.main;
const result = await postgres.query(`SELECT id, lead_email, scheduled_at, attempts FROM lead_followups WHERE scheduled_at <= CURRENT_TIMESTAMP AND status = 'pending' AND attempts < 3 ORDER BY scheduled_at ASC LIMIT 20`);
return result.rows.map(row => ({ json: row }));

const followup = $input.first().json;
const postgres = Postgres.main;
await postgres.query(`UPDATE lead_followups SET attempts = attempts + 1, last_attempt = CURRENT_TIMESTAMP, status = CASE WHEN attempts + 1 >= 3 THEN 'completed' ELSE 'pending' END WHERE id = $1`, [followup.id]);
const isRetry = followup.attempts >= 1;
return [{ json: { channel: '#sales-followups', severity: isRetry ? 'medium' : 'low', dedupeKey: `followup_${followup.id}_${followup.attempts + 1}`, text: isRetry ? `⚠️ *Follow-up RETRY*
*Lead:* ${followup.lead_email}
*Attempt:* ${followup.attempts + 1}/3
> Manual review recommended` : `📞 *Follow-up Reminder*
*Lead:* ${followup.lead_email}
*Follow-up ID:* ${followup.id}`, metadata: { flow: 'followup', followupId: followup.id, attempts: followup.attempts + 1 } } }];
